style.css:
@-moz-document domain("github.com") {
/* ThoughtWorks Color Theme - CSS Variable System */
:root,
[data-color-mode="light"],
[data-color-mode="dark"],
[data-color-mode="auto"] {
    /* ============================================
       THOUGHTWORKS COLOR PALETTE
       ============================================ */
    --tw-light-gray: #EDF1F3;
    --tw-bright-pink: #F2617A;
    --tw-dark-pink: #bd4257;
    --tw-dark-teal: #003D4F;
    --tw-orange: #CC850A;
    --tw-sage-green: #6B9E78;
    --tw-light-teal: #47A1AD;
    --tw-purple: #634F7D;
    --tw-white: #FFFFFF;
    --tw-dark-gray: #e5e7eb;

    /* ============================================
       BACKGROUND COLORS
       ============================================ */
    --bg-primary: #1a2632;
    --bg-secondary: #191632;
    --bg-tertiary: #243447;
    --bg-quaternary: #121b23;
    --bg-muted: var(--bg-tertiary);
    --bg-hover: var(--bg-secondary);
    --bg-active: var(--bg-primary);

    /* ============================================
       TEXT COLORS
       ============================================ */
    --text-primary: #FFFFFF;
    --text-secondary: #9e9e9e;
    --text-tertiary: #929292;
    --text-muted: #607d8b;
    --text-quaternary: #969ab0;
    --text-quinary: #6d6d72;
    --text-icon: #8899a6;
    --text-disabled: #aeaeae;

    /* ============================================
       BORDER COLORS
       ============================================ */
    --border-default: var(--tw-dark-gray);
    --border-muted: rgba(229, 231, 235, 0.5);
    --border-emphasis: var(--tw-dark-gray);

    /* ============================================
       LINK & ACCENT COLORS
       ============================================ */
    --link-default: var(--tw-light-teal);
    --link-hover: var(--tw-sage-green);
    --link-visited: var(--tw-purple);

    /* ============================================
       SUCCESS COLORS (Sage Green)
       ============================================ */
    --success-fg: var(--tw-sage-green);
    --success-bg: var(--tw-sage-green);
    --success-bg-muted: rgba(107, 158, 120, 0.1);
    --success-border: var(--tw-sage-green);

    /* ============================================
       DANGER COLORS (Bright Pink)
       ============================================ */
    --danger-fg: var(--tw-bright-pink);
    --danger-bg: var(--tw-bright-pink);
    --danger-bg-muted: rgba(242, 97, 122, 0.1);
    --danger-border: var(--tw-bright-pink);

    /* ============================================
       WARNING COLORS (Orange)
       ============================================ */
    --warning-fg: var(--tw-orange);
    --warning-bg: var(--tw-orange);
    --warning-bg-muted: rgba(204, 133, 10, 0.15);
    --warning-border: var(--tw-orange);

    /* ============================================
       INFO/DONE COLORS (Purple)
       ============================================ */
    --info-fg: var(--tw-purple);
    --info-bg: var(--tw-purple);
    --info-bg-muted: rgba(99, 79, 125, 0.15);
    --info-border: var(--tw-purple);

    /* ============================================
       BUTTON COLORS
       ============================================ */
    --btn-primary-bg: var(--tw-sage-green);
    --btn-primary-bg-hover: #5a8a66;
    --btn-primary-bg-active: #4a7a56;
    --btn-primary-fg: var(--tw-white);
    --btn-primary-border: var(--tw-sage-green);
    --btn-default-bg: var(--bg-primary);
    --btn-default-bg-hover: var(--bg-secondary);
    --btn-default-fg: var(--text-primary);
    --btn-default-border: var(--border-default);

    /* ============================================
       CODE SYNTAX HIGHLIGHTING
       ============================================ */
    --code-string: var(--tw-light-teal);
    --code-keyword: var(--tw-purple);
    --code-variable: var(--tw-orange);
    --code-entity: var(--tw-light-teal);
    --code-constant: var(--tw-orange);
    --code-comment: #bbb;

    /* ============================================
       DIFF COLORS
       ============================================ */
    --diff-add-fg: var(--tw-sage-green);
    --diff-add-bg: rgba(107, 158, 120, 0.1);
    --diff-del-fg: var(--tw-bright-pink);
    --diff-del-bg: rgba(242, 97, 122, 0.1);

    /* ============================================
       LEGACY GITHUB VARIABLES (for compatibility)
       ============================================ */
    --fgColor-default: var(--text-primary) !important;
    --bgColor-default: var(--bg-primary) !important;
    --color-canvas-default: var(--bg-primary) !important;

    /* Accent Colors - Links */
    --fgColor-accent: var(--link-default) !important;
    --color-accent-fg: var(--link-default) !important;
    --color-accent-emphasis: var(--link-default) !important;
    --bgColor-accent-emphasis: var(--link-default) !important;
    --bgColor-accent-muted: rgba(71, 161, 173, 0.1) !important;
    --borderColor-accent-emphasis: var(--link-default) !important;
    --borderColor-accent-muted: rgba(71, 161, 173, 0.4) !important;

    /* Success/Green Colors */
    --bgColor-success-emphasis: var(--success-bg) !important;
    --bgColor-success-muted: var(--success-bg-muted) !important;
    --fgColor-success: var(--success-fg) !important;
    --color-success-fg: var(--success-fg) !important;
    --borderColor-success-emphasis: var(--success-border) !important;
    --borderColor-success-muted: rgba(107, 158, 120, 0.4) !important;

    /* Danger/Error Colors - Pink */
    --bgColor-danger-emphasis: var(--danger-bg) !important;
    --bgColor-danger-muted: var(--danger-bg-muted) !important;
    --fgColor-danger: var(--danger-fg) !important;
    --color-danger-fg: var(--danger-fg) !important;
    --borderColor-danger-emphasis: var(--danger-border) !important;
    --borderColor-danger-muted: rgba(242, 97, 122, 0.4) !important;

    /* Attention/Warning Colors - Orange */
    --bgColor-attention-emphasis: var(--warning-bg) !important;
    --bgColor-attention-muted: var(--warning-bg-muted) !important;
    --fgColor-attention: var(--warning-fg) !important;
    --color-attention-fg: var(--warning-fg) !important;
    --borderColor-attention-emphasis: var(--warning-border) !important;
    --borderColor-attention-muted: rgba(204, 133, 10, 0.4) !important;

    /* Done/Purple Colors */
    --bgColor-done-emphasis: var(--info-bg) !important;
    --bgColor-done-muted: var(--info-bg-muted) !important;
    --fgColor-done: var(--info-fg) !important;
    --borderColor-done-emphasis: var(--info-border) !important;
    --borderColor-done-muted: rgba(99, 79, 125, 0.4) !important;

    /* Border Colors */
    --borderColor-default: var(--border-default) !important;
    --borderColor-emphasis: var(--border-emphasis) !important;
    --color-border-default: var(--border-default) !important;
    --color-border-muted: var(--border-muted) !important;

    /* Muted Backgrounds */
    --bgColor-muted: var(--bg-muted) !important;
    --color-canvas-subtle: var(--bg-muted) !important;

    /* Button Colors */
    --button-primary-bgColor: var(--btn-primary-bg) !important;
    --button-primary-bgColor-hover: var(--btn-primary-bg-hover) !important;
    --button-primary-bgColor-active: var(--btn-primary-bg-active) !important;
    --button-primary-borderColor: var(--btn-primary-border) !important;
    --button-primary-fgColor: var(--btn-primary-fg) !important;

    /* Code Syntax Highlighting */
    --color-prettylights-syntax-string: var(--code-string) !important;
    --color-prettylights-syntax-keyword: var(--code-keyword) !important;
    --color-prettylights-syntax-variable: var(--code-variable) !important;
    --color-prettylights-syntax-entity: var(--code-entity) !important;
    --color-prettylights-syntax-constant: var(--code-constant) !important;

    /* Diff Colors */
    --color-diff-blob-addition-num-text: var(--diff-add-fg) !important;
    --color-diff-blob-addition-fg: var(--diff-add-fg) !important;
    --color-diff-blob-addition-line-bg: var(--diff-add-bg) !important;
    --color-diff-blob-deletion-num-text: var(--diff-del-fg) !important;
    --color-diff-blob-deletion-fg: var(--diff-del-fg) !important;
    --color-diff-blob-deletion-line-bg: var(--diff-del-bg) !important;

    /* Link Colors */
    --color-link-fg: var(--link-default) !important;
    --color-link-hover-fg: var(--link-hover) !important;

    /* State Colors */
    --bgColor-open-emphasis: var(--danger-bg) !important;
    --bgColor-open-muted: var(--danger-bg-muted) !important;
    --borderColor-open-emphasis: var(--danger-border) !important;
    --borderColor-open-muted: rgba(242, 97, 122, 0.4) !important;

    --bgColor-severe-emphasis: var(--tw-dark-pink) !important;
    --bgColor-severe-muted: rgba(189, 66, 87, 0.1) !important;
    --borderColor-severe-emphasis: var(--tw-dark-pink) !important;
    --borderColor-severe-muted: rgba(189, 66, 87, 0.4) !important;
}

/* Additional GitHub Dark Theme Selectors */
[data-color-mode="dark"],
[data-color-mode="dark"][data-dark-theme="dark"],
[data-color-mode="auto"][data-light-theme*="dark"],
[data-color-mode="light"][data-light-theme*="dark"] {
    --color-fg-default: #FFFFFF !important;
    --color-canvas-default: #1a2632 !important;
    --color-accent-fg: #47A1AD !important;
    --color-success-fg: #6B9E78 !important;
    --color-danger-fg: #F2617A !important;
    --color-attention-fg: #CC850A !important;
    --color-done-fg: #634F7D !important;
    --color-border-default: #e5e7eb !important;
    --color-border-muted: rgba(229, 231, 235, 0.5) !important;
    --color-link-fg: #47A1AD !important;
    --color-link-hover-fg: #6B9E78 !important;

    /* Button Variables */
    --button-primary-bgColor: #6B9E78 !important;
    --button-primary-bgColor-hover: #5a8a66 !important;
    --button-primary-bgColor-active: #4a7a56 !important;
    --button-primary-borderColor: #6B9E78 !important;
    --button-primary-fgColor: #FFFFFF !important;

    /* Code Highlighting */
    --color-prettylights-syntax-string: #47A1AD !important;
    --color-prettylights-syntax-keyword: #634F7D !important;
    --color-prettylights-syntax-variable: #CC850A !important;
    --color-prettylights-syntax-entity: #47A1AD !important;
    --color-prettylights-syntax-constant: #CC850A !important;
    --color-prettylights-syntax-storage-modifier-import: #634F7D !important;
    --color-prettylights-syntax-markup-bold: #FFFFFF !important;

    /* Diff Colors */
    --color-diff-blob-addition-num-text: #6B9E78 !important;
    --color-diff-blob-addition-fg: #6B9E78 !important;
    --color-diff-blob-addition-line-bg: rgba(107, 158, 120, 0.1) !important;
    --color-diff-blob-deletion-num-text: #F2617A !important;
    --color-diff-blob-deletion-fg: #F2617A !important;
    --color-diff-blob-deletion-line-bg: rgba(242, 97, 122, 0.1) !important;
}

/* HTML Global */

body {
    background-color: var(--bg-primary);
    color: var(--text-primary);
}

p {
    color: var(--text-muted) !important;
}

h4 {
    color: var(--text-primary);
}


/* Class Global */

.lead {
    color: var(--text-tertiary);
}


/* Main Site and New User */

.site-header {
    background-color: var(--bg-tertiary);
}

.site-header-nav .nav-item {
    color: var(--text-primary);
}

.jumbotron-home {
    background-image: none;
    background-color: var(--bg-primary);
}

.features-list .list-divider,
.setup-form .tos-info,
.setup-form .setup-organization-next {
    border-color: var(--borderColor-default) !important;
}

.radio-label {
    border-color: var(--borderColor-default) !important;
}

.tag-input-tag {
    background: var(--bg-tertiary);
}

.tag-input-tag .remove {
    background: var(--bg-primary);
}

.home-hero-signup .form-control-lg {
    border-color: var(--borderColor-default) !important;
}

.shade-gray {
    background-color: var(--bg-quaternary) !important;
}

.tile-block {
    border-color: var(--borderColor-default) !important;
}

.tile-bordered:not(:last-child) {
    border-color: var(--borderColor-default) !important;
}


/* Main Site Login */

.session-authentication {
    background-color: var(--bg-primary);
}

.session-authentication .header-logo {
    color: var(--text-primary);
}

.session-authentication .auth-form-body {
    border-color: var(--borderColor-default) !important;
}

.auth-form-body {
    background-color: var(--bg-primary);
}

.session-authentication .create-account-callout {
    border-color: var(--borderColor-default) !important;
}

.session-authentication .auth-form-header {
    color: var(--text-primary);
}


/* Site Wide Global */

.header {
    background-color: var(--bg-tertiary);
    border-color: var(--borderColor-default) !important;
}

.header-logo-invertocat {
    color: var(--text-primary);
}

.header-search-scope {
    border-color: var(--borderColor-default) !important;
}

.header-nav-link {
    color: var(--text-primary);
}


/*.scoped-search .form-control .header-search-scope {
    background-color: var(--bg-primary);
    border-color: var(--borderColor-default)!important;
}*/

.form-control,
.form-select {
    color: var(--text-primary);
    background-color: var(--bg-secondary);
    border-color: var(--borderColor-default) !important;
}

.form-control.focus,
.form-control:focus,
.form-select.focus,
.form-select:focus {
    box-shadow: none;
}

.form-group .form-control:focus {
    background-color: var(--bg-secondary);
}

.btn {
    color: var(--text-primary);
    background-color: var(--bg-primary);
    background-image: none;
    border-color: var(--borderColor-default) !important;
}

.btn:hover,
.btn:active,
.btn.zeroclipboard-is-hover,
.btn.zeroclipboard-is-active {
    text-decoration: none;
    background-color: var(--bg-secondary);
    background-image: none;
    border-color: var(--borderColor-default) !important;
}

.btn:active,
.btn.selected,
.btn.zeroclipboard-is-active {
    background-color: var(--bg-primary);
    background-image: none;
    border-color: var(--borderColor-default) !important;
}

.btn-primary {
    color: var(--text-primary);
    background-color: var(--btn-primary-bg);
    background-image: none;
    border-color: var(--borderColor-default) !important;
}

.btn-theme-green {
    background-color: var(--btn-primary-bg);
}

.site-footer {
    border-color: var(--borderColor-default) !important;
}

.dropdown-menu {
    background-color: var(--bg-primary);
    border: 1px solid var(--borderColor-default) !important;
    box-shadow: none;
}

.dropdown-divider {
    background-color: var(--borderColor-default) !important;
}

.dropdown-item {
    color: var(--text-secondary);
}

.dropdown-item:hover {
    background-color: var(--bg-tertiary);
}

button.dropdown-item.dropdown-signout {
    color: var(--danger-fg);
}


/* Site Related */

.setup-header {
    border-color: var(--borderColor-default) !important;
}


/* Home */

.news .alert {
    border-color: var(--borderColor-default) !important;
}

.news .alert .octicon {
    color: var(--text-icon);
}

.news .alert .branch-link,
.news .alert .pull-info {
    color: var(--text-primary);
    background: var(--bg-tertiary);
}

.ajax-pagination-form .ajax-pagination-d {
    background: var(--bg-tertiary);
}

.boxed-group>h3,
.boxed-group .heading {
    color: var(--text-primary);
    background-color: var(--bg-tertiary);
    border-color: var(--borderColor-default) !important;
}

.boxed-group-inner {
    background: var(--bg-primary);
    border: 1px solid var(--borderColor-default) !important;
}

.mini-repo-list-item {
    border-color: var(--borderColor-default) !important;
}

.mini-repo-list-item .repo-icon {
    color: var(--text-icon);
}

.private .mini-repo-list-item {
    background-color: var(--bg-tertiary);
}

.private .mini-repo-list-item .repo-icon {
    color: var(--warning-fg);
}

.filter-bar {
    background-color: var(--bg-primary);
    border-bottom: 1px solid var(--borderColor-default) !important;
}

.boxed-group .counter {
    color: var(--text-primary);
    background-color: var(--bg-primary);
    border: 1px var(--borderColor-default) !important;
}

.subscribe-feed {
    color: var(--text-quinary);
}

.protip-callout {
    border-color: var(--borderColor-default) !important;
}

.octofication .broadcast-icon-mask {
    background-color: var(--bg-primary);
}

.link-gray-dark {
    color: var(--link-default) !important;
}

.more-repos {
    text-align: center;
    background-color: var(--bg-tertiary);
    box-shadow: none;
    border-top: 1px solid var(--borderColor-default) !important;
}


/* New Repo */

.outline-box-highlighted {
    background-color: var(--bg-primary);
    border-color: var(--borderColor-default) !important;
}

.outline-box {
    border: solid 1px var(--borderColor-default) !important;
}

.copyable-terminal {
    background-color: var(--bg-secondary);
}

.reponame-suggestion {
    color: var(--success-fg);
}


/* Repo Page (Main) */

.repohead.experiment-repo-nav {
    background-color: var(--bg-secondary);
}

.pagehead {
    border-color: var(--borderColor-default) !important;
}

.repository-meta {
    color: var(--text-secondary);
}

.social-count {
    color: var(--text-muted);
    background-color: var(--bg-secondary);
    border: 1px solid var(--borderColor-default) !important;
    border-left: 0;
}

.user-mention,
.team-mention {
    color: var(--link-default);
}

.reponav-item {
    color: var(--text-secondary);
}

.reponav-item:hover,
.reponav-item:focus {
    color: var(--text-primary);
}

.counter {
    background-color: var(--bg-secondary);
    border: 1px var(--borderColor-default) !important;
}

.reponav-item .counter {
    color: var(--text-primary);
}

.reponav-item.selected {
    color: var(--text-primary);
    background-color: var(--bg-primary);
    border-color: var(--warning-border) var(--borderColor-default) transparent !important;
    border: 1px solid var(--borderColor-default) !important;
}

.btn.selected:hover {
    background-color: var(--bg-secondary);
}

.overall-summary {
    border-color: var(--borderColor-default) !important;
}

.text-emphasized {
    color: var(--text-primary);
}

.numbers-summary a,
.numbers-summary .nolink {
    color: var(--text-quaternary);
}

.repository-lang-stats-graph {
    border-color: var(--borderColor-default) !important;
}

.repository-lang-stats ol.repository-lang-stats-numbers li .language-color {
    border: 1px var(--borderColor-default) !important;
}

.repository-lang-stats ol.repository-lang-stats-numbers li .lang {
    color: var(--text-primary);
}

table.files {
    background: var(--bg-primary);
}

table.files tr.navigation-focus td {
    background: var(--bg-secondary);
}

table.files td {
    border-color: var(--borderColor-default) !important;
}

table.files td.icon {
    color: var(--text-primary);
}

.warning {
    padding: 0.5em;
    margin-bottom: 0.8em;
    font-weight: bold;
    background-color: var(--warning-bg);
}

.file-wrap {
    border-color: var(--borderColor-default) !important;
}

.commit-author-section {
    color: var(--text-secondary);
}

.commit-tease {
    color: var(--info-fg);
    background-color: var(--bg-tertiary);
    border-color: var(--borderColor-default) !important;
}

.commits-list-item .commit-author {
    color: var(--link-default);
}

.commit-tease-sha {
    color: var(--link-default);
}

.commit-tease-contributors {
    background-color: var(--bg-secondary);
    border-color: var(--borderColor-default) !important;
}

.commit .commit-title a {
    color: var(--link-default);
}

.branch-infobar {
    background-color: var(--bg-primary);
    border-color: var(--border-default);
}

.full-commit {
    background: var(--bg-primary);
    border: 1px solid var(--border-default);
}

.full-commit p.commit-title {
    color: var(--link-default);
}

.full-commit .commit-meta {
    background: var(--bg-tertiary);
    border-color: var(--border-default);
}

.full-commit .sha-block {
    color: var(--text-primary);
}

.full-commit .sha-block>.sha {
    color: var(--text-secondary);
}

.full-commit .btn-outline,
.full-commit .btn-outline:disabled {
    border-color: var(--border-default);
}

.commits-list-item.navigation-focus {
    background: var(--bg-secondary);
}

.file-navigation .get-repo-btn {
    border-color: var(--border-default);
}

.file-navigation .get-repo-btn:first-child {
    border-color: var(--border-default);
}

.signed-commit-badge {
    border-color: var(--border-default);
}

.signed-commit-signer-name .signer {
    display: block;
    font-weight: bold;
    color: var(--link-default);
}

.flex-table-item-primary {
    color: var(--text-primary);
}

span.d-block {
    color: var(--text-primary);
}

.signed-commit-header {
    background-color: var(--bg-tertiary);
    border-color: var(--border-default);
}


/* Repo Blame */

.blame-commit-title,
.blame-commit-title .message {
    color: var(--link-default);
}

.blame-commit,
.blame-commit+.blame-line {
    border-color: var(--border-default);
}

.blame-blob-num {
    background-color: var(--bg-tertiary);
}

.muted-link {
    color: var(--link-default) !important;
}


/* README Markdown Live */
.markdown-title {
    color: var(--bgColor-danger-emphasis) !important;
}

.readme .markdown-body,
.snippet-clipboard-content,
.readme .plain {
    background-color: var(--bg-tertiary);
    border: 1px solid var(--border-default) !important;
    border-radius: 8px !important;
}

.markdown-body .highlight pre,
.markdown-body pre {
    background-color: var(--bg-tertiary);
    border: 1px solid var(--border-default) !important;
    border-radius: 8px !important;
}

.markdown-body h1 {
    border-color: var(--border-default) !important;
}

.markdown-body img {
    background-color: var(--bg-tertiary) !important;
}

.markdown-body h1 .octicon-link,
.markdown-body h2 .octicon-link,
.markdown-body h3 .octicon-link,
.markdown-body h4 .octicon-link,
.markdown-body h5 .octicon-link,
.markdown-body h6 .octicon-link {
    color: var(--text-primary) !important;
}

.markdown-body table tr {
    background-color: var(--bg-primary) !important;
